    'KILOMETRE' => kilometre,
    'MILE' => mile,
    'UNKNOWN' => unknown,
    _ => throw ArgumentError.value(
      symbol,
      'symbol',
      'not a symbol of CarDistanceUnit',
    ),
  };
}

