  /// A copy with the given fields replaced. A null argument keeps the field,
  /// so `copyWith` cannot set a nullable field to null.
  Document copyWith({
    String? title,
    String? fileName,
    String? mediaType,
    Uint8List? content,
    AxtDate? dated,
    String? notes,
    List<AxtRelation>? relations,
    List<AxtExtension>? extensions,
  }) => Document(
    title: title ?? this.title,
    fileName: fileName ?? this.fileName,
    mediaType: mediaType ?? this.mediaType,
    content: content ?? this.content,
    dated: dated ?? this.dated,
    notes: notes ?? this.notes,
    relations: relations ?? this.relations,
    extensions: extensions ?? this.extensions,
  );

  @override
  bool operator ==(Object other) =>
      other is Document &&
      other.title == title &&
      other.fileName == fileName &&
      other.mediaType == mediaType &&
      _deepEquals(other.content, content) &&
      other.dated == dated &&
      other.notes == notes &&
      _deepEquals(other.relations, relations) &&
      _deepEquals(other.extensions, extensions);

  @override
  int get hashCode => Object.hash(
    title,
    fileName,
    mediaType,
    _deepHash(content),
    dated,
    notes,
    _deepHash(relations),
    _deepHash(extensions),
  );

  @override
  String toString() =>
      'Document(title: $title, fileName: $fileName, mediaType: $mediaType, content: $content, dated: $dated, notes: $notes, relations: $relations, extensions: $extensions)';
}

/// A calendar date of the proleptic Gregorian calendar, of which a part may be unknown, such as a birthday without a year (null, 5, 3), a year alone (2019, null, null) or a month of a year (2027, 3, null). At least one part is not null, and a day has its month. Defined in spec/time.md. Its schema never changes.
final class AxtDate {
  const AxtDate({this.year, this.month, this.day});

  /// The year, 1 to 9999. Null when the year is not known or does not matter.
  final int? year;

  /// The month of the year, 1 (January) to 12 (December). Null when the month is not known; then day is null as well.
  final int? month;

  /// The day of the month, 1 to the number of days of the month: of that year when the year is known, otherwise of a leap year, so that 29 February is valid without a year. Null when the day is not known.
  final int? day;

  /// The schema of [AxtDate] and the conversion from and to the generic values of AvroCodec.
  static final AvroType<AxtDate> avroType = AvroType<AxtDate>(
    schemaJson: '''{
  "doc": "A calendar date of the proleptic Gregorian calendar, of which a part may be unknown, such as a birthday without a year (null, 5, 3), a year alone (2019, null, null) or a month of a year (2027, 3, null). At least one part is not null, and a day has its month. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "default": null,
      "doc": "The year, 1 to 9999. Null when the year is not known or does not matter.",
      "name": "year",
      "type": [
        "null",
        "int"
      ]
    },
    {
      "default": null,
      "doc": "The month of the year, 1 (January) to 12 (December). Null when the month is not known; then day is null as well.",
      "name": "month",
      "type": [
        "null",
        "int"
      ]
    },
    {
      "default": null,
      "doc": "The day of the month, 1 to the number of days of the month: of that year when the year is known, otherwise of a leap year, so that 29 February is valid without a year. Null when the day is not known.",
      "name": "day",
      "type": [
        "null",
        "int"
      ]
    }
  ],
  "name": "Date",
  "namespace": "axt",
  "type": "record"
}''',
    toAvro: (value) => <String, Object?>{
      'year': value.year,
      'month': value.month,
      'day': value.day,
    },
    fromAvro: (value) {
      final m = value as Map<String, Object?>;
      return AxtDate(
        year: m['year'] as int?,
        month: m['month'] as int?,
        day: m['day'] as int?,
      );
    },
  );

  /// A copy with the given fields replaced. A null argument keeps the field,
  /// so `copyWith` cannot set a nullable field to null.
  AxtDate copyWith({int? year, int? month, int? day}) => AxtDate(
    year: year ?? this.year,
    month: month ?? this.month,
    day: day ?? this.day,
  );

  @override
  bool operator ==(Object other) =>
      other is AxtDate &&
      other.year == year &&
      other.month == month &&
      other.day == day;

  @override
  int get hashCode => Object.hash(year, month, day);

  @override
  String toString() => 'AxtDate(year: $year, month: $month, day: $day)';
}

/// One measured value or count at a point in time, such as a weight, a blood pressure reading or a tally of glasses of water.
final class Measurement {
  const Measurement({
    required this.quantity,
    required this.value,
    required this.unit,
    required this.measuredAt,
    required this.subject,
    required this.notes,
    required this.relations,
    required this.extensions,
  });

