  Pet copyWith({
    String? name,
    String? species,
    String? breed,
    PetSex? sex,
    bool? neutered,
    AxtDate? birthday,
    String? microchip,
    String? notes,
    List<AxtRelation>? relations,
    List<AxtExtension>? extensions,
