      other.breed == breed &&
      other.sex == sex &&
      other.neutered == neutered &&
      other.birthday == birthday &&
      other.microchip == microchip &&
      other.notes == notes &&
      _deepEquals(other.relations, relations) &&
      _deepEquals(other.extensions, extensions);

