    species,
    breed,
    sex,
    neutered,
    birthday,
    microchip,
    notes,
    _deepHash(relations),
    _deepHash(extensions),
  );

  @override
  String toString() =>
      'Pet(name: $name, species: $species, breed: $breed, sex: $sex, neutered: $neutered, birthday: $birthday, microchip: $microchip, notes: $notes, relations: $relations, extensions: $extensions)';
}

/// The pet's sex.
enum PetSex {
  unknown('UNKNOWN'),
  female('FEMALE'),
  male('MALE');

  const PetSex(this.symbol);

  /// The Avro symbol of the value.
  final String symbol;

  /// The value of the Avro symbol [symbol]. Throws [ArgumentError] for any other string.
  static PetSex fromSymbol(String symbol) => switch (symbol) {
    'UNKNOWN' => unknown,
    'FEMALE' => female,
    'MALE' => male,
    _ => throw ArgumentError.value(symbol, 'symbol', 'not a symbol of PetSex'),
  };
}

/// A task: something the user wants to do, possibly by a due date, possibly repeating.
final class Task {
  const Task({
    required this.title,
    required this.notes,
    this.due,
    required this.dueAllDay,
    this.repeat,
    required this.done,
    this.doneAt,
    required this.priority,
    required this.relations,
    required this.extensions,
  });

  /// What is to be done, as plain text on one line.
