    schemaJson: '''{"axt.version":1,"doc":"A task: something the user wants to do, possibly by a due date, possibly repeating.","fields":[{"default":"","doc":"What is to be done, as plain text on one line.","name":"title","type":"string"},{"default":"","doc":"Free notes on the task, as plain text; lines are separated by LF. Empty when there are none.","name":"notes","type":"string"},{"default":null,"doc":"The date and time on the wall clock by which the task is due, in a time zone or floating; see due_all_day. Null when the task has no due date.","name":"due","type":["null",{"doc":"A date and time on the wall clock, to the millisecond, either in a time zone of the IANA time zone database, with the offset from UTC and the instant as the writer's zone rules gave them, or floating, on the wall clock of wherever the user is, without zone, offset and instant. Defined in spec/time.md. Its schema never changes.","fields":[{"doc":"The year of the proleptic Gregorian calendar, 1 to 9999.","name":"year","type":"int"},{"doc":"The month, 1 (January) to 12 (December).","name":"month","type":"int"},{"doc":"The day of the month, 1 to the number of days of that month in that year.","name":"day","type":"int"},{"doc":"The hour on the wall clock, 0 to 23.","name":"hour","type":"int"},{"doc":"The minute, 0 to 59.","name":"minute","type":"int"},{"doc":"The second, 0 to 59; a leap second is not written as 60.","name":"second","type":"int"},{"doc":"The millisecond, 0 to 999.","name":"millisecond","type":"int"},{"default":null,"doc":"The name of the time zone in the IANA time zone database, such as Europe/Berlin. Null for a floating time; then offset_seconds and instant_ms are null as well.","name":"zone","type":["null","string"]},{"default":null,"doc":"The offset of the wall clock from UTC, in seconds, -64800 to 64800, as the writer's rules of the zone gave it at the instant, such as 3600 for 01:00 east of UTC. Null for a floating time, and only then.","name":"offset_seconds","type":["null","int"]},{"default":null,"doc":"The instant, in milliseconds since 1970-01-01T00:00:00Z without leap seconds: the wall clock read as if it were UTC, minus offset_seconds. Null for a floating time, and only then.","name":"instant_ms","type":["null","long"]}],"name":"DateTime","namespace":"axt","type":"record"}]},{"default":false,"doc":"True when the task is due on the day of due without a time of day; due is then floating at 00:00, and its time has no meaning.","name":"due_all_day","type":"boolean"},{"default":null,"doc":"How the task repeats: the value of an RFC 5545 RRULE property without the RRULE: prefix, such as FREQ=WEEKLY;BYDAY=TU. The occurrences start at due, on the wall clock of its time zone, or of wherever the user is when due is floating. Null when the task does not repeat.","name":"repeat","type":["null","string"]},{"default":false,"doc":"True when the task is done. For a repeating task: the occurrence at due is done.","name":"done","type":"boolean"},{"default":null,"doc":"When the task was marked done. Null when it is not done or the time is not known.","name":"done_at","type":["null","axt.DateTime"]},{"default":"NONE","doc":"How important the task is.","name":"priority","type":{"default":"NONE","doc":"How important the task is.","name":"TaskPriority","symbols":["NONE","LOW","MEDIUM","HIGH"],"type":"enum"}},{"default":[],"doc":"The relations of the record to other records and to things outside AXT (spec/types.md, section 8), in the order the user gave them. Empty when it has none.","name":"relations","type":{"items":{"axt.emoji":"🔗","axt.help":"A link to another entry or to something outside, such as the pet an appointment is for.","axt.help_translations":{"de":"Eine Verknüpfung mit einem anderen Eintrag oder mit etwas außerhalb, etwa mit dem Tier, für das ein Termin ist."},"axt.label":"Relation","axt.label_translations":{"de":"Verknüpfung"},"doc":"A relation: a link from the record that holds it to another record or to a thing outside AXT, of a kind, with information about the link. Defined in spec/fields.md, section 11.","fields":[{"axt.advanced":true,"axt.emoji":"🆔","axt.help":"The id of this relation.","axt.help_translations":{"de":"Die ID dieser Verknüpfung."},"axt.label":"Relation id","axt.label_translations":{"de":"Verknüpfungs-ID"},"doc":"The id of the relation, a UUID in lower-case hexadecimal, unique among the relations of the record that holds it and kept for as long as the relation exists.","name":"id","type":{"logicalType":"uuid","type":"string"}},{"axt.emoji":"🔖","axt.help":"What kind of link this is.","axt.help_translations":{"de":"Welche Art von Verknüpfung das ist."},"axt.label":"Kind","axt.label_translations":{"de":"Art"},"default":"axt.related","doc":"The kind of the relation, a name in a namespace, written like the full name of a type, such as org.example.catalog.patient. axt.related, the only kind AXT defines, says only that the two are related. A receiver shows a kind it does not know as a relation of that name.","name":"kind","type":"string"},{"axt.emoji":"🎯","axt.help":"What is linked.","axt.help_translations":{"de":"Was verknüpft ist."},"axt.label":"Target","axt.label_translations":{"de":"Ziel"},"doc":"What the relation points at: a record, or a thing outside AXT.","name":"target","type":[{"axt.emoji":"📄","axt.help":"An entry of this app or of another.","axt.help_translations":{"de":"Ein Eintrag dieser App oder einer anderen."},"axt.label":"Entry","axt.label_translations":{"de":"Eintrag"},"doc":"A record as the target of a relation: by its id and its sender.","fields":[{"axt.advanced":true,"axt.emoji":"🆔","axt.help":"The id of the linked entry.","axt.help_translations":{"de":"Die ID des verknüpften Eintrags."},"axt.label":"Entry id","axt.label_translations":{"de":"Eintrags-ID"},"doc":"The id of the target record.","name":"id","type":{"logicalType":"uuid","type":"string"}},{"axt.advanced":true,"axt.emoji":"🔑","axt.help":"The app the linked entry comes from.","axt.help_translations":{"de":"Die App, von der der verknüpfte Eintrag kommt."},"axt.label":"Sender","axt.label_translations":{"de":"Absender"},"default":null,"doc":"A key of the device set of the target record's sender. Null when the target is a record of the sender of the record that holds the relation.","name":"sender","type":["null",{"doc":"An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md.","name":"RelationRecordTargetSender","size":32,"type":"fixed"}]},{"axt.advanced":true,"axt.emoji":"🧩","axt.help":"The type of the linked entry.","axt.help_translations":{"de":"Der Typ des verknüpften Eintrags."},"axt.label":"Type","axt.label_translations":{"de":"Typ"},"default":"","doc":"The full name of the target record's type, which holds its major version, such as axt.example.v1.Pet. Empty when not known.","name":"type","type":"string"},{"axt.emoji":"💬","axt.help":"What to show for the linked entry.","axt.help_translations":{"de":"Was für den verknüpften Eintrag angezeigt wird."},"axt.label":"Display text","axt.label_translations":{"de":"Anzeigetext"},"default":"","doc":"A text to show for the target while the record itself is not at hand, such as its title. Empty when there is none.","name":"text","type":"string"}],"name":"RelationRecordTarget","type":"record"},{"axt.emoji":"🌐","axt.help":"Something that is not an entry, such as a web page.","axt.help_translations":{"de":"Etwas, das kein Eintrag ist, etwa eine Webseite."},"axt.label":"Outside thing","axt.label_translations":{"de":"Etwas außerhalb"},"doc":"A thing outside AXT as the target of a relation: by a URI.","fields":[{"axt.emoji":"🔗","axt.format":"uri","axt.help":"The address of the linked thing.","axt.help_translations":{"de":"Die Adresse des verknüpften Dings."},"axt.label":"URI","axt.label_translations":{"de":"URI"},"doc":"A URI of RFC 3986 that names the thing, of any scheme, such as https: or urn:. Not empty.","name":"uri","type":"string"},{"axt.emoji":"💬","axt.help":"What to show for the linked thing.","axt.help_translations":{"de":"Was für das verknüpfte Ding angezeigt wird."},"axt.label":"Display text","axt.label_translations":{"de":"Anzeigetext"},"default":"","doc":"A text to show for the thing, such as its name. Empty when there is none.","name":"text","type":"string"}],"name":"RelationOutsideTarget","type":"record"}]},{"axt.emoji":"📝","axt.help":"Something about this link.","axt.help_translations":{"de":"Etwas zu dieser Verknüpfung."},"axt.label":"Note","axt.label_translations":{"de":"Notiz"},"axt.multiline":true,"default":"","doc":"Free text about the link. Empty when there is none.","name":"note","type":"string"},{"axt.emoji":"▶️","axt.help":"When the link begins.","axt.help_translations":{"de":"Wann die Verknüpfung beginnt."},"axt.label":"From","axt.label_translations":{"de":"Ab"},"default":null,"doc":"When the link begins, such as the day a pet came to its keeper. Null when it has no beginning or it is not known.","name":"start","type":["null","axt.DateTime"]},{"axt.emoji":"⏹️","axt.help":"When the link ends.","axt.help_translations":{"de":"Wann die Verknüpfung endet."},"axt.label":"Until","axt.label_translations":{"de":"Bis"},"default":null,"doc":"The first moment after the link, as for the end of an appointment. Null when it has no end or it is not known.","name":"end","type":["null","axt.DateTime"]},{"axt.advanced":true,"axt.emoji":"🗂️","axt.help":"Further details of the link.","axt.help_translations":{"de":"Weitere Angaben zur Verknüpfung."},"axt.label":"Details","axt.label_translations":{"de":"Details"},"default":{},"doc":"Further values that the kind of the relation needs, by names its kind gives them. Empty when there are none.","name":"attributes","type":{"type":"map","values":"string"}}],"name":"Relation","namespace":"axt","type":"record"},"type":"array"}},{"default":[],"doc":"The extensions of the record: records of the apps' own types that add fields of their own to it (spec/fields.md, section 12), at most one of each type. Empty when it has none.","name":"extensions","type":{"items":{"axt.emoji":"🧩","axt.help":"Further fields that an app adds to this entry.","axt.help_translations":{"de":"Weitere Felder, die eine App diesem Eintrag hinzufügt."},"axt.label":"Extension","axt.label_translations":{"de":"Erweiterung"},"doc":"An extension: one record of an app's own type that the app adds to a record of another type, such as the fields of its own that a cat-a-log adds to a Pet, held as the bytes of its single-object encoding. Defined in spec/fields.md, section 12.","fields":[{"axt.advanced":true,"axt.emoji":"🔖","axt.help":"The type of this extension.","axt.help_translations":{"de":"Der Typ dieser Erweiterung."},"axt.label":"Extension type","axt.label_translations":{"de":"Erweiterungstyp"},"doc":"The full name of the extension's record type, such as org.example.catalog.CatExtension, which holds its major version, of at most 256 bytes; at most one extension of a name in a list.","name":"name","type":"string"},{"axt.advanced":true,"axt.emoji":"📦","axt.help":"The values of this extension.","axt.help_translations":{"de":"Die Werte dieser Erweiterung."},"axt.label":"Extension data","axt.label_translations":{"de":"Erweiterungsdaten"},"doc":"The extension's record in single-object encoding: the marker C3 01, the fingerprint of its writer schema as 8 bytes in little-endian order, and the record's Avro binary encoding. Passed on unchanged by an app that does not know the type.","name":"data","type":"bytes"}],"name":"Extension","namespace":"axt","type":"record"},"type":"array"}}],"name":"Task","namespace":"axt.example.v1","type":"record"}''',
    toAvro: (value) => <String, Object?>{
      'title': value.title,
      'notes': value.notes,
      'due': switch (value.due) {
        final v0? => AxtDateTime.avroType.toAvro(v0),
        null => null,
      },
      'due_all_day': value.dueAllDay,
      'repeat': value.repeat,
      'done': value.done,
      'done_at': switch (value.doneAt) {
        final v0? => AxtDateTime.avroType.toAvro(v0),
        null => null,
      },
      'priority': value.priority.symbol,
      'relations': [
        for (final x0 in value.relations) AxtRelation.avroType.toAvro(x0),
      ],
      'extensions': [
        for (final x0 in value.extensions) AxtExtension.avroType.toAvro(x0),
      ],
    },
    fromAvro: (value) {
      final m = value as Map<String, Object?>;
      return Task(
        title: m['title'] as String,
        notes: m['notes'] as String,
        due: switch (m['due']) {
          final v0? => AxtDateTime.avroType.fromAvro(v0),
          null => null,
        },
        dueAllDay: m['due_all_day'] as bool,
        repeat: m['repeat'] as String?,
        done: m['done'] as bool,
        doneAt: switch (m['done_at']) {
          final v0? => AxtDateTime.avroType.fromAvro(v0),
          null => null,
        },
        priority: TaskPriority.fromSymbol(m['priority'] as String),
        relations: [
          for (final x0 in m['relations'] as List<Object?>)
            AxtRelation.avroType.fromAvro(x0),
        ],
        extensions: [
          for (final x0 in m['extensions'] as List<Object?>)
            AxtExtension.avroType.fromAvro(x0),
        ],
      );
    },
  );

  /// A copy with the given fields replaced. A null argument keeps the field,
  /// so `copyWith` cannot set a nullable field to null.
  Task copyWith({
    String? title,
    String? notes,
    AxtDateTime? due,
    bool? dueAllDay,
    String? repeat,
    bool? done,
    AxtDateTime? doneAt,
    TaskPriority? priority,
    List<AxtRelation>? relations,
    List<AxtExtension>? extensions,
  }) => Task(
    title: title ?? this.title,
    notes: notes ?? this.notes,
    due: due ?? this.due,
    dueAllDay: dueAllDay ?? this.dueAllDay,
    repeat: repeat ?? this.repeat,
    done: done ?? this.done,
    doneAt: doneAt ?? this.doneAt,
    priority: priority ?? this.priority,
    relations: relations ?? this.relations,
    extensions: extensions ?? this.extensions,
  );

  @override
  bool operator ==(Object other) =>
      other is Task &&
      other.title == title &&
      other.notes == notes &&
      other.due == due &&
      other.dueAllDay == dueAllDay &&
      other.repeat == repeat &&
      other.done == done &&
      other.doneAt == doneAt &&
      other.priority == priority &&
      _deepEquals(other.relations, relations) &&
      _deepEquals(other.extensions, extensions);

  @override
  int get hashCode => Object.hash(
    title,
    notes,
    due,
    dueAllDay,
    repeat,
    done,
    doneAt,
    priority,
    _deepHash(relations),
    _deepHash(extensions),
  );

  @override
  String toString() =>
      'Task(title: $title, notes: $notes, due: $due, dueAllDay: $dueAllDay, repeat: $repeat, done: $done, doneAt: $doneAt, priority: $priority, relations: $relations, extensions: $extensions)';
}

/// How important the task is.
enum TaskPriority {
  none('NONE'),
  low('LOW'),
  medium('MEDIUM'),
  high('HIGH');

  const TaskPriority(this.symbol);

  /// The Avro symbol of the value.
  final String symbol;

  /// The value of the Avro symbol [symbol]. Throws [ArgumentError] for any other string.
  static TaskPriority fromSymbol(String symbol) => switch (symbol) {
    'NONE' => none,
    'LOW' => low,
    'MEDIUM' => medium,
    'HIGH' => high,
    _ => throw ArgumentError.value(
      symbol,
      'symbol',
      'not a symbol of TaskPriority',
    ),
  };
}

/// Whether [a] and [b] are equal, comparing lists and maps by their elements.
bool _deepEquals(Object? a, Object? b) {
  if (a is List<Object?> && b is List<Object?>) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!_deepEquals(a[i], b[i])) return false;
    }
    return true;
  }
  if (a is Map<Object?, Object?> && b is Map<Object?, Object?>) {
    if (a.length != b.length) return false;
    for (final e in a.entries) {
      if (!b.containsKey(e.key) || !_deepEquals(e.value, b[e.key])) {
        return false;
      }
    }
    return true;
  }
  return a == b;
}

/// The hash code of [value] that fits [_deepEquals].
int _deepHash(Object? value) => switch (value) {
  final List<Object?> list => Object.hashAll(list.map(_deepHash)),
  final Map<Object?, Object?> map => Object.hashAllUnordered(
    map.entries.map((e) => Object.hash(e.key, _deepHash(e.value))),
  ),
  _ => value.hashCode,
};
